class Solution {
    public String reversePrefix(String word, char ch) {
        int index = word.indexOf(ch);
        if (index == -1) {
            return word;
        }
        StringBuilder prefix = new StringBuilder(word.substring(0, index + 1));
        prefix.reverse();
        return prefix.append(word.substring(index + 1)).toString();
    }
}

class Solution {
    public String reversePrefix(String word, char ch) {
        char[] chars = word.toCharArray();
        int end = -1;
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] == ch) {
                end = i;
                break;
            }
        }
        if (end == -1) {
            return word;
        }
        int left = 0;
        int right = end;
        while (left < right) {
            char temp = chars[left];
            chars[left++] = chars[right];
            chars[right--] = temp;
        }
        return new String(chars);
    }
}

class Solution {
    public String reversePrefix(String word, char ch) {
        int end = -1;
        for (int i = 0; i < word.length(); i++) {
            if (word.charAt(i) == ch) {
                end = i;
                break;
            }
        }
        if (end == -1) {
            return word;
        }
        StringBuilder answer = new StringBuilder(word.length());
        for (int i = end; i >= 0; i--) {
            answer.append(word.charAt(i));
        }
        for (int i = end + 1; i < word.length(); i++) {
            answer.append(word.charAt(i));
        }
        return answer.toString();
    }
}

import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public String reversePrefix(String word, char ch) {
        int end = word.indexOf(ch);
        if (end == -1) {
            return word;
        }
        Deque<Character> stack = new ArrayDeque<>();
        for (int i = 0; i <= end; i++) {
            stack.push(word.charAt(i));
        }
        StringBuilder answer = new StringBuilder(word.length());
        while (!stack.isEmpty()) {
            answer.append(stack.pop());
        }
        answer.append(word.substring(end + 1));
        return answer.toString();
    }
}
